export function Props({
  text = "{{text}}",
  color = "{{color}}",
  size = "{{size}}",
  uppercase = {{uppercase}},
}) {
  const dims = { sm: { padding: "4px 10px", fontSize: 11 }, md: { padding: "8px 18px", fontSize: 14 }, lg: { padding: "12px 26px", fontSize: 18 } }[size];
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 280, boxSizing: "border-box", textAlign: "center" }}>
      <code style={{ display: "block", fontFamily: "ui-monospace, monospace", fontSize: 11, background: "#24143012", padding: "8px 10px", borderRadius: 6, marginBottom: 10, wordBreak: "break-all", textAlign: "left" }}>{`{ text: "${text}", color: "${color}", size: "${size}", uppercase: ${uppercase} }`}</code>
      <span style={{ display: "block", fontSize: 10, color: "#24143080", marginBottom: 12 }} aria-hidden="true">&darr; passed as props</span>
      <span style={{ display: "inline-block", borderRadius: 999, fontWeight: 700, color: "#241430", background: color, textTransform: uppercase ? "uppercase" : "none", letterSpacing: uppercase ? ".04em" : "normal", ...dims }}>{text}</span>
    </div>
  );
}
